#include <stdint.h>

int32_t ceil_log2_u32(uint32_t x) {
    if (x <= 1) return 0;
    return 32 - __builtin_clz(x - 1);
}

#include <stdint.h>

uint32_t gray_decode_u32(uint32_t g) {
    g ^= g >> 1;
    g ^= g >> 2;
    g ^= g >> 4;
    g ^= g >> 8;
    g ^= g >> 16;
    return g;
}

#include <stdint.h>

int32_t sat_add_s32(int32_t a, int32_t b) {
    int64_t s = (int64_t)a + b;
    if (s > INT32_MAX) return INT32_MAX;
    if (s < INT32_MIN) return INT32_MIN;
    return (int32_t)s;
}

#include <stdint.h>

uint32_t avg_ceil_u32(uint32_t x, uint32_t y) {
    return (x | y) - ((x ^ y) >> 1);
}

#include <stdint.h>

int32_t abs32(int32_t x) {
    int32_t m = x >> 31;
    return (x ^ m) - m;
}

#include <stdint.h>

uint8_t clamp_u8(int32_t a) {
    if (a < 0) return 0;
    if (a > 255) return 255;
    return (uint8_t)a;
}
